mapper.select:
WITH region AS (SELECT ST_Union(geom) AS geom FROM data_ad_region WHERE name IN
#{name} ) SELECT rock_group, characteristics, project_name FROM ( SELECT rock_group, characteristics, project_name,
ROW_NUMBER() OVER (PARTITION BY rock_group ORDER BY (SELECT NULL)) AS rn FROM data_engineering_geology d, region WHERE ST_Intersects( d.geom, region.geom ) ) t WHERE rn = 1;

WITH region AS (SELECT ST_Union(geom) AS geom FROM data_ad_region WHERE name IN
#{name} ) SELECT aquifer_rock, aquifer_type, water_abundance, rock_group_era, distribution_pos, burial_conditions FROM ( SELECT aquifer_rock, aquifer_type, water_abundance, rock_group_era, distribution_pos, burial_conditions,
ROW_NUMBER() OVER (PARTITION BY aquifer_rock, aquifer_type ORDER BY (SELECT NULL)) AS rn FROM data_hydro_geology d, region WHERE ST_Intersects( d.geom, region.geom ) ) t WHERE rn = 1;

WITH region AS (SELECT ST_Union(geom) AS geom FROM data_ad_region WHERE name IN
#{name} ) SELECT code, label, stratum_era, stratum_system, stratum_series, stratum_member, description, stratum_group, lithology FROM ( SELECT code, label, stratum_era, stratum_system, stratum_series, stratum_member, description, stratum_group, lithology,
ROW_NUMBER() OVER (PARTITION BY code ORDER BY (SELECT NULL)) AS rn FROM data_stratum d, region WHERE ST_Intersects( d.geom, region.geom ) ) t WHERE rn = 1;
